import gzip
import random
import zipfile
from pathlib import Path

import polars as pl
import pytest

from just_vcf.formats import get_spec
from just_vcf.loaders.rsid_table import FORMATS as RSID_FORMATS
from just_vcf.loading import Loaded, UnsupportedFormatError, load
from just_vcf.schema import CALLS, FACETS, canonical_chrom
from just_vcf.sniff import sniff

PREAMBLE_23 = (
    "# This data file generated by 23andMe at: Wed Apr 11 08:10:59 2018\n"
    "#\n"
    "# We are using reference human assembly build 37 (also known as Annotation Release 104).\n"
    "#\n"
    "# rsid\tchromosome\tposition\tgenotype\n"
)


def _data_rows(text: str, delimiter: str = "\t") -> list[list[str]]:
    """The data rows of a 23andMe-layout text, split, as the test's own reading of the file."""
    rows = []
    for line in text.replace("\r\n", "\n").split("\n"):
        stripped = line.lstrip('"')
        if not line.strip() or stripped.startswith("#") or line[1:].startswith("#"):
            continue
        rows.append(line.split(delimiter))
    return rows


def _load_text(tmp_path: Path, text: str | bytes, name: str = "genome.txt") -> Loaded:
    path = tmp_path / name
    path.write_bytes(text if isinstance(text, bytes) else text.encode())
    return load(path)


@pytest.mark.parametrize("format_id", sorted(RSID_FORMATS))
def test_every_loadable_example_round_trips(tmp_path: Path, format_id: str) -> None:
    spec = get_spec(format_id)
    rows = _data_rows(spec.example, spec.delimiter or "\t")
    loaded = _load_text(tmp_path, spec.example)
    calls = loaded.calls.collect()
    facet = loaded.facets.collect()

    assert calls.schema == CALLS
    assert facet.schema == FACETS
    assert facet["format_id"].to_list() == [format_id]
    assert calls.height == len(rows)
    assert sorted(calls["source_gt"].to_list()) == sorted(r[3] for r in rows)
    assert set(calls["ids"].list.first().to_list()) == {r[0] for r in rows}
    assert sorted(zip(calls["chrom"], calls["pos"])) == sorted((canonical_chrom(r[1]), int(r[2])) for r in rows)
    no_calls = {r[0] for r in rows if r[3] in spec.no_call}
    all_null = calls.filter(pl.col("gt_alleles").list.eval(pl.element().is_null()).list.all())
    assert set(all_null["ids"].list.first().to_list()) == no_calls
    assert calls["ref"].null_count() == calls.height, "an array writes no REF; REF comes from the sequence only"
    assert calls["evidence_basis"].to_list() == ["assay"] * calls.height
    # A 23andMe export too small for any generation's row band says its chip is unknown (RM4).
    chip_lines = [f"chip unknown: {len(rows)} rows"] if format_id in ("23andme", "23andme_csv") else []
    assert [w.split(",")[0] for w in loaded.warnings] == chip_lines


def test_genotype_encodings(tmp_path: Path) -> None:
    body = (
        "rs1\t1\t100\tAG\n"
        "rs2\tX\t200\tA\n"
        "rs3\t1\t300\tT-\n"
        "rs4\t1\t400\t--\n"
        "i5\t1\t500\tDI\n"
        "i6\t1\t600\tII\n"
        "rs7\tMT\t700\tG\n"
    )
    calls = _load_text(tmp_path, PREAMBLE_23 + body).calls.collect()
    by_id = {row["ids"][0]: row for row in calls.iter_rows(named=True)}
    assert by_id["rs1"]["gt_alleles"] == ["A", "G"] and by_id["rs1"]["end_pos"] == 100
    assert by_id["rs2"]["gt_alleles"] == ["A"] and by_id["rs2"]["end_pos"] == 200
    assert by_id["rs3"]["gt_alleles"] == ["T", None] and by_id["rs3"]["end_pos"] == 300
    assert by_id["rs4"]["gt_alleles"] == [None, None] and by_id["rs4"]["end_pos"] is None
    assert by_id["i5"]["gt_alleles"] == ["D", "I"] and by_id["i5"]["end_pos"] is None
    assert by_id["i6"]["gt_alleles"] == ["I", "I"] and by_id["i6"]["end_pos"] is None
    assert by_id["rs7"]["chrom"] == "MT"
    assert all(row["phased"] is None and row["alts"] is None for row in by_id.values())


def test_rows_that_do_not_fit_are_dropped_and_counted(tmp_path: Path) -> None:
    body = (
        "rs1\t1\t100\tAG\n"
        "rs2\t1\t200\tA\tG\n"
        "rs3\t1\t300\n"
        "rs4\t1\tnot_a_number\tCC\n"
        "rs5\t1\t4294967296\tCC\n"
        "rs6\t1\t600\tCCA\n"
        "rs7\t1\t700\tNN\n"
    )
    loaded = _load_text(tmp_path, PREAMBLE_23 + body)
    calls = loaded.calls.collect()
    assert set(calls["ids"].list.first().to_list()) == {"rs1", "rs6", "rs7"}
    unreadable = calls.filter(pl.col("gt_alleles").is_null())
    assert sorted(unreadable["source_gt"].to_list()) == ["CCA", "NN"]
    assert len(loaded.warnings) == 4
    assert any(w.startswith("chip unknown: 3 rows") for w in loaded.warnings)
    assert any(w.startswith("2 row(s) without exactly 4 fields") and "3, 5" in w for w in loaded.warnings)
    assert any(w.startswith("2 row(s) with a position") for w in loaded.warnings)
    assert any(w.startswith("2 genotype(s) not readable") for w in loaded.warnings)


def test_a_doubled_tab_after_the_id_is_read_past_and_counted(tmp_path: Path) -> None:
    """F2: 2012–2014 23andMe exports write some rows with an empty field between id and chromosome.
    Only that place is read past; an empty field elsewhere still drops the row."""
    body = (
        "rs1\t1\t100\tAG\n"
        "rs15842\t\t1\t948921\tCT\n"
        "rs7533\t\tX\t1479333\tA\n"
        "rs548049170\t1\t69869\t\tTT\n"
        "rs9\t\t\t1\t900\tCC\n"
        "rs10\n"
    )
    loaded = _load_text(tmp_path, PREAMBLE_23 + body)
    calls = loaded.calls.collect()
    got = {r["ids"][0]: (r["chrom"], r["pos"], r["source_gt"], r["gt_alleles"]) for r in calls.iter_rows(named=True)}
    assert got == {
        "rs1": ("1", 100, "AG", ["A", "G"]),
        "rs15842": ("1", 948921, "CT", ["C", "T"]),
        "rs7533": ("X", 1479333, "A", ["A"]),
    }
    assert any(w.startswith("2 row(s) with an empty field between the id and the chromosome") for w in loaded.warnings)
    assert any(w.startswith("3 row(s) without exactly 4 fields") and "1, 5, 6" in w for w in loaded.warnings)


def test_an_appended_export_in_another_layout_is_named_not_read(tmp_path: Path) -> None:
    """F3: a headerless 23andMe-shaped export followed by an AncestryDNA-shaped one (five fields)."""
    first = "".join(f"rs{i}\t1\t{100 + i}\tAG\n" for i in range(1, 4))
    second = "".join(f"rs{i}\t1\t{100 + i}\tA\tG\n" for i in range(1, 1001))
    loaded = _load_text(tmp_path, first + second, "two.txt")
    assert loaded.facets.collect()["format_id"].to_list() == ["rsid_table_headerless"]
    assert loaded.calls.select(pl.len()).collect().item() == 3
    assert any(w.startswith("the last 1000 data row(s) all have 5 fields") and "after the first 3 data row(s)" in w for w in loaded.warnings)
    short = _load_text(tmp_path, first + second[: second.index("rs3\t")], "short.txt")
    assert not any(w.startswith("the last") for w in short.warnings), "a few odd rows are not an export"


def test_array_contig_codes_are_canonical_and_mapped(tmp_path: Path) -> None:
    body = "rs1\t23\t100\tA\nrs2\t24\t100\tC\nrs3\t25\t100\tAG\nrs4\t26\t100\tT\nrs5\tchrM\t50\tT\n"
    loaded = _load_text(tmp_path, "# rsid\tchromosome\tposition\tgenotype\n" + body)
    assert loaded.calls.collect()["chrom"].to_list() == ["X", "Y", "MT", "MT", "XY"]
    mapping = loaded.facets.collect()["contig_map"][0].to_list()
    assert mapping == [
        {"source": "23", "chrom": "X"},
        {"source": "24", "chrom": "Y"},
        {"source": "25", "chrom": "XY"},
        {"source": "26", "chrom": "MT"},
        {"source": "chrM", "chrom": "MT"},
    ]


def test_preamble_quirks_and_line_endings(tmp_path: Path) -> None:
    spec = get_spec("genes_for_good")
    stray = "I" + spec.example
    expected = _load_text(tmp_path, spec.example, "a.txt").calls.collect().drop("facet_id")
    for name, text in {
        "stray.txt": stray.encode(),
        "crlf.txt": spec.example.replace("\n", "\r\n").encode(),
        "cr.txt": spec.example.replace("\n", "\r").encode(),
        "utf16.txt": spec.example.encode("utf-16"),
    }.items():
        path = tmp_path / name
        path.write_bytes(text)
        assert sniff(path).format == "genes_for_good", name
        assert load(path).calls.collect().drop("facet_id").equals(expected), name


def test_load_is_deterministic_and_order_free(tmp_path: Path) -> None:
    rows = [f"rs{i}\t{random.Random(i).choice(['1', '2', '10', 'X', 'MT'])}\t{1000 + i}\tAG\n" for i in range(200)]
    first = _load_text(tmp_path, PREAMBLE_23 + "".join(rows), "one.txt")
    again = load(tmp_path / "one.txt")
    assert first.calls.collect().equals(again.calls.collect())
    assert first.facets.collect().equals(again.facets.collect())

    shuffled = rows[:]
    random.Random(7).shuffle(shuffled)
    other = _load_text(tmp_path, PREAMBLE_23 + "".join(shuffled), "two.txt")
    assert other.calls.collect().drop("facet_id").equals(first.calls.collect().drop("facet_id"))
    assert other.facets.collect()["facet_id"][0] != first.facets.collect()["facet_id"][0], "different bytes"


def test_archive_member_is_loaded_and_recorded(tmp_path: Path) -> None:
    spec = get_spec("23andme")
    path = tmp_path / "export.zip"
    with zipfile.ZipFile(path, "w") as zf:
        zf.writestr("genome_Full.txt", gzip.compress(spec.example.encode()))
    loaded = load(path)
    facet = loaded.facets.collect().row(0, named=True)
    assert facet["member"] == "genome_Full.txt"
    assert loaded.calls.collect().height == len(_data_rows(spec.example))


def test_formats_without_a_loader_are_refused(tmp_path: Path) -> None:
    for name, text in {"summary.tsv": get_spec("cgi_summary").example, "notes.txt": "just some notes\n"}.items():
        path = tmp_path / name
        path.write_text(text)
        with pytest.raises(UnsupportedFormatError):
            load(path)


def test_real_23andme_export(pgp_participants: Path) -> None:
    candidates = sorted(pgp_participants.glob("*/upload-*/genome*Full*.txt"))[:40]
    found = next((p for p in candidates if sniff(p).format == "23andme"), None)
    if found is None:
        pytest.skip("no plain 23andMe export among the first candidates")
    text = found.read_bytes().decode("utf-8", errors="replace")
    rows = _data_rows(text)
    loaded = load(found)
    calls = loaded.calls.collect()
    assert calls.height == len(rows)
    assert calls.filter(pl.col("gt_alleles").list.eval(pl.element().is_null()).list.all()).height == sum(
        r[3].strip() == "--" for r in rows
    )
    assert set(calls["ids"].list.first().to_list()) == {r[0] for r in rows}
    assert calls["pos"].to_list() == canonical_positions(calls)
    assert loaded.facets.collect()["assembly_label"][0] in {"GRCh36", "GRCh37"}


def canonical_positions(calls: pl.DataFrame) -> list[int]:
    """Positions are sorted within each contig block of the canonical order."""
    ordered: list[int] = []
    for _, block in calls.group_by("chrom", maintain_order=True):
        ordered += sorted(block["pos"].to_list())
    return ordered
